<?php $s=$record['snapshot'];$summary=$s['summary'];?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Fechamento Mensal do CQ - <?=htmlspecialchars($record['unit_name'])?></title><link rel="stylesheet" href="/assets/css/monthly-closures.css"></head><body class="mc-pdf"><header><img src="/assets/images/bloodhub-logo-horizontal.png" alt="BloodHub"><div><h1>FECHAMENTO MENSAL DO CONTROLE DE QUALIDADE</h1><p>Comprovante histórico - Snapshot versão <?=$record['version_number']?></p></div></header><section class="pdf-ident"><div><span>Processamento</span><strong><?=htmlspecialchars($record['unit_name'])?></strong></div><div><span>Mês/Ano</span><strong><?=htmlspecialchars($s['period']['label'])?></strong></div><div><span>Data do fechamento</span><strong><?=date('d/m/Y H:i',strtotime($record['closed_at']))?></strong></div><div><span>Responsável</span><strong><?=htmlspecialchars($record['closed_by_name'])?></strong></div></section><section class="pdf-summary"><?php foreach(['production'=>'Produção','required'=>'Exigido','sent'=>'Enviado','qc_completed'=>'CQ concluído']as$k=>$label):?><div><span><?=$label?></span><strong><?=$summary[$k]?></strong></div><?php endforeach;?><div><span>Pendências</span><strong><?=count($s['pending_items'])?></strong></div></section><h2>Resumo por hemocomponente</h2><table><thead><tr><th>Hemocomponente</th><th>Produzido</th><th>Exigido</th><th>Enviado</th><th>Pendente</th><th>CQ concluído</th><th>Amostragem</th></tr></thead><tbody><?php foreach($s['components']as$r):?><tr><td><?=htmlspecialchars($r['code'].' - '.$r['name'])?></td><td><?=$r['produced']===null?'Não informada':$r['produced']?></td><td><?=$r['required']?></td><td><?=$r['sent']?></td><td><?=$r['pending']?></td><td><?=$r['qc_completed']?></td><td><?=$r['sampling_status']==='MET'?'ATENDIDA':'ABAIXO DO MÍNIMO'?></td></tr><?php endforeach;?></tbody></table><h2>Pendências e justificativas</h2><?php if($s['pending_items']):?><ul><?php foreach($s['pending_items']as$p):?><li><strong><?=htmlspecialchars($p['category'])?>:</strong> <?=htmlspecialchars($p['message'])?></li><?php endforeach;?></ul><?php else:?><p>Nenhuma pendência registrada no momento do fechamento.</p><?php endif;?><div class="pdf-note"><strong>Observação/justificativa:</strong><p><?=nl2br(htmlspecialchars($record['closure_notes']?:'Sem observações.'))?></p></div><footer><strong>Fechado por <?=htmlspecialchars($record['closed_by_name'])?> em <?=date('d/m/Y H:i',strtotime($record['closed_at']))?>.</strong><span>Assinatura eletrônica nominal · Snapshot capturado em <?=date('d/m/Y H:i',strtotime($s['captured_at']))?></span></footer><script>window.addEventListener('load',()=>setTimeout(()=>window.print(),150))</script></body></html>
